for (unsigned a=1; a<=6; ++a) for (unsigned b=0; b<16; ++b) {
    auto funciona=[&](vector<unsigned> extras) {
        vector<bool> visto(a+1,false);
        unsigned x=0;
        for(unsigned j=0;j<a;++j) { visto[j]=true; x^=j; }
        for(unsigned j:extras) { if(j<=a) visto[j]=true; x^=j; }
        return x==b && !visto[a];
    };
    unsigned ref=a+3;
    if(funciona({})) ref=a;
    for(unsigned i=0;i<32;++i) {
        if(funciona({i})) ref=min(ref,a+1);
        for(unsigned j=0;j<32;++j)
            if(funciona({i,j})) ref=min(ref,a+2);
    }
    assert(menorTamanho(a,b)==ref);
}

