auto atende=[](long long n, int d) {
    vector<long long> divs;
    for(long long x=1;x<=n/x;++x) if(n%x==0) {
        divs.push_back(x);
        if(x!=n/x) divs.push_back(n/x);
    }
    sort(divs.begin(),divs.end());
    if(divs.size()<4) return false;
    for(size_t i=1;i<divs.size();++i) if(divs[i]-divs[i-1]<d) return false;
    return true;
};
for(int d=1;d<=30;++d) {
    long long ref=1;
    while(!atende(ref,d)) ++ref;
    assert(menorInteiroSeparado(d)==ref);
}
assert(atende(menorInteiroSeparado(10000),10000));

